    .ifndef RENDER
    .equ RENDER, 0                # Override with -Wa,--defsym,RENDER=1
    .endif
    .ifndef TEST_CASE
    .equ TEST_CASE, 0             # 0=T6, 1=solved, 2=short, 3=own distance-11
    .endif
    .if TEST_CASE < 0
    .error "TEST_CASE must be 0, 1, 2 or 3"
    .endif
    .if TEST_CASE > 3
    .error "TEST_CASE must be 0, 1, 2 or 3"
    .endif
    .if RENDER
    # Pass these exported Ripes I/O symbols with GNU as --defsym.
    # No MMIO address is assumed. See LED_RENDERER.md.
    .ifndef LED_MATRIX_0_BASE
    .error "Supply LED_MATRIX_0_BASE from Ripes I/O exported symbols"
    .endif
    .ifndef LED_MATRIX_0_WIDTH
    .error "Supply LED_MATRIX_0_WIDTH from Ripes I/O exported symbols"
    .endif
    .ifndef LED_MATRIX_0_HEIGHT
    .error "Supply LED_MATRIX_0_HEIGHT from Ripes I/O exported symbols"
    .endif
    .if LED_MATRIX_0_WIDTH != 35
    .error "LED Matrix Width must be 35"
    .endif
    .if LED_MATRIX_0_HEIGHT != 25
    .error "LED Matrix Height must be 25"
    .endif
    .ifndef RENDER_DELAY
    .equ RENDER_DELAY, 100000     # Busy-loop iterations, not milliseconds
    .endif
    .endif

# Hand-edited RV32I embedded solver. No host gates or libc calls.
# main parses target_input, runs IDA*, stores result_length/solution_path.
# Return codes: 0=solved, 1=search failed, 2=invalid input.
    .option nopic
    .attribute arch, "rv32i2p1"
    .attribute stack_align, 16
    .text

    .align 2
    .globl main
    .type main, @function
main:
    addi sp,sp,-48
    sw ra,44(sp)
    lui t0,%hi(result_length)
    li t1,-2
    sw t1,%lo(result_length)(t0)
    lui a0,%hi(target_input)
    addi a0,a0,%lo(target_input)
    mv a1,sp
    call parse_target
    beq a0,zero,.Lembedded_invalid
    .if RENDER
    mv a0,sp
    call render_init
    .endif
    mv a0,sp
    lui a1,%hi(solution_path)
    addi a1,a1,%lo(solution_path)
    call ida_star
    lui t0,%hi(result_length)
    sw a0,%lo(result_length)(t0)
    .if RENDER
    call render_solution
    lui t0,%hi(result_length)
    lw a0,%lo(result_length)(t0)
    .endif
    srai a0,a0,31
    andi a0,a0,1
    j .Lembedded_return
.Lembedded_invalid:
    li a0,2
.Lembedded_return:
    lw ra,44(sp)
    addi sp,sp,48

    # Ripes Exit2: a0 = 0 success, 1 search failure, 2 invalid input.
    li a7,93
    ecall

.Lhalt:
    j .Lhalt
    .size main, .-main

# Leaf parser: a0=NUL-terminated 14 digits, a1=14-byte state.
    .align 2
    .type parse_target, @function
parse_target:
    mv t0,a0
    li t1,14
.Linput_length:
    lbu t2,0(t0)
    beq t2,zero,.Linput_bad
    addi t0,t0,1
    addi t1,t1,-1
    bne t1,zero,.Linput_length
    lbu t2,0(t0)
    bne t2,zero,.Linput_bad
    li t0,0
    li t1,0
    li t2,0
.Linput_digits:
    lbu t3,0(a0)
    addi t3,t3,-49
    li t4,7
    bgeu t3,t4,.Linput_bad
    li t4,1
    sll t4,t4,t3
    and t5,t1,t4
    bne t5,zero,.Linput_bad
    or t1,t1,t4
    sb t3,0(a1)
    lbu t3,7(a0)
    addi t3,t3,-49
    li t4,3
    bgeu t3,t4,.Linput_bad
    sb t3,7(a1)
    add t2,t2,t3
    addi a0,a0,1
    addi a1,a1,1
    addi t0,t0,1
    li t4,7
    bne t0,t4,.Linput_digits
    li t4,3
.Linput_mod3:
    bltu t2,t4,.Linput_sum
    addi t2,t2,-3
    j .Linput_mod3
.Linput_sum:
    seqz a0,t2
    ret
.Linput_bad:
    li a0,0
    ret
    .size parse_target, .-parse_target
