    .globl target_input
    .type target_input, @object
# Exactly one input is emitted; selection adds no runtime instructions.
target_input:
    .if TEST_CASE == 0
    .asciz "21345671111111"
    .endif
    .if TEST_CASE == 1
    .asciz "12345671111111"
    .endif
    .if TEST_CASE == 2
    .asciz "25314672313211"
    .endif
    .if TEST_CASE == 3
    .asciz "12345672121232"
    .endif
    .size target_input, .-target_input
    .bss
    .align 2
.LANCHOR1:
    .type search_stack, @object
search_stack:
    .zero 72
    .size search_stack,72
    .globl solution_path
    .type solution_path, @object
solution_path:
    .zero 11
    .size solution_path,11
    .align 2
    .globl result_length
    .type result_length, @object
result_length:
    .zero 4
    .size result_length,4

    .if RENDER
    .text
    .align 2
# a0 points to the parsed cubie state. Search never touches render_state.
render_init:
    addi sp,sp,-16
    sw ra,12(sp)
    lui t0,%hi(render_state)
    addi t0,t0,%lo(render_state)
    li t1,14
.Lrender_copy:
    lbu t2,0(a0)
    sb t2,0(t0)
    addi a0,a0,1
    addi t0,t0,1
    addi t1,t1,-1
    bne t1,zero,.Lrender_copy
    li t0,LED_MATRIX_0_BASE
    li t1,LED_MATRIX_0_WIDTH * LED_MATRIX_0_HEIGHT
.Lrender_clear:
    sw zero,0(t0)
    addi t0,t0,4
    addi t1,t1,-1
    bne t1,zero,.Lrender_clear
    call draw_cube
    lw ra,12(sp)
    addi sp,sp,16
    ret

# Replay only the final solution, including R2/R' as one displayed move.
render_solution:
    addi sp,sp,-16
    sw ra,12(sp)
    sw s0,8(sp)
    sw s1,4(sp)
    lui t0,%hi(result_length)
    lw s1,%lo(result_length)(t0)
    li s0,0
.Lrender_replay:
    bge s0,s1,.Lrender_done
    call render_pause
    lui t0,%hi(solution_path)
    addi t0,t0,%lo(solution_path)
    add t0,t0,s0
    lbu a0,0(t0)
    call render_apply_move
    call draw_cube
    addi s0,s0,1
    j .Lrender_replay
.Lrender_done:
    lw s1,4(sp)
    lw s0,8(sp)
    lw ra,12(sp)
    addi sp,sp,16
    ret

render_pause:
    li t0,RENDER_DELAY
.Lrender_wait:
    beq t0,zero,.Lrender_wait_done
    addi t0,t0,-1
    j .Lrender_wait
.Lrender_wait_done:
    ret

# a0=move ID 0..8. Full maps use the same convention as solver.c.
# Temporary destination avoids overwriting source cubies during a cycle.
render_apply_move:
    slli t0,a0,3
    sub t0,t0,a0
    lui a1,%hi(render_sources)
    addi a1,a1,%lo(render_sources)
    add a1,a1,t0
    lui a2,%hi(render_twists)
    addi a2,a2,%lo(render_twists)
    add a2,a2,t0
    lui a3,%hi(render_state)
    addi a3,a3,%lo(render_state)
    lui a4,%hi(render_next)
    addi a4,a4,%lo(render_next)
    li a5,0
.Lrender_map:
    lbu t0,0(a1)
    add t0,a3,t0
    lbu t1,0(t0)
    sb t1,0(a4)
    lbu t1,7(t0)
    lbu t2,0(a2)
    add t1,t1,t2
    li t2,3
    bltu t1,t2,.Lrender_twisted
    addi t1,t1,-3
.Lrender_twisted:
    sb t1,7(a4)
    addi a1,a1,1
    addi a2,a2,1
    addi a4,a4,1
    addi a5,a5,1
    li t0,7
    bne a5,t0,.Lrender_map
    lui t0,%hi(render_next)
    addi t0,t0,%lo(render_next)
    li t1,14
.Lrender_commit:
    lbu t2,0(t0)
    sb t2,0(a3)
    addi t0,t0,1
    addi a3,a3,1
    addi t1,t1,-1
    bne t1,zero,.Lrender_commit
    ret

# a0=x, a1=y, a2=0x00RRGGBB. Caller supplies in-range coordinates.
# Width is assembly-checked above; no multiplication instructions.
    .globl draw_pixel
draw_pixel:
    li t0,LED_MATRIX_0_BASE
    slli t1,a1,5
    slli t2,a1,1
    add t1,t1,t2
    add t1,t1,a1
    add t1,t1,a0
    slli t1,t1,2
    add t0,t0,t1
    sw a2,0(t0)
    ret

# 24 descriptors: x,y,corner,orientation-slot. Fixed corner is index 7.
# Cubie color index = (destination slot + internal orientation) mod 3.
    .globl draw_cube
draw_cube:
    addi sp,sp,-32
    sw ra,28(sp)
    sw s0,24(sp)
    sw s1,20(sp)
    sw s2,16(sp)
    sw s3,12(sp)
    sw s4,8(sp)
    sw s5,4(sp)
    lui s0,%hi(render_facelets)
    addi s0,s0,%lo(render_facelets)
    li s1,24
.Lrender_facelet:
    lbu s2,0(s0)
    lbu s3,1(s0)
    lbu t0,2(s0)
    lbu t1,3(s0)
    li t2,7
    beq t0,t2,.Lrender_fixed
    lui t2,%hi(render_state)
    addi t2,t2,%lo(render_state)
    add t2,t2,t0
    lbu t0,0(t2)
    lbu t2,7(t2)
    add t1,t1,t2
    li t2,3
    bltu t1,t2,.Lrender_fixed
    addi t1,t1,-3
.Lrender_fixed:
    slli t2,t0,1
    add t0,t0,t2
    add t0,t0,t1
    lui t1,%hi(render_colors)
    addi t1,t1,%lo(render_colors)
    add t0,t0,t1
    lbu t0,0(t0)
    slli t0,t0,2
    lui t1,%hi(render_palette)
    addi t1,t1,%lo(render_palette)
    add t0,t0,t1
    lw s4,0(t0)
    li s5,0
.Lrender_rectangle:
    andi a0,s5,3
    add a0,a0,s2
    srli a1,s5,2
    add a1,a1,s3
    mv a2,s4
    call draw_pixel
    addi s5,s5,1
    li t0,12
    bne s5,t0,.Lrender_rectangle
    addi s0,s0,4
    addi s1,s1,-1
    bne s1,zero,.Lrender_facelet
    lw s5,4(sp)
    lw s4,8(sp)
    lw s3,12(sp)
    lw s2,16(sp)
    lw s1,20(sp)
    lw s0,24(sp)
    lw ra,28(sp)
    addi sp,sp,32
    ret
    .section .rodata
    .align 2
render_palette:
    .word 0x00ffffff,0x00ff8000,0x0000ff00,0x00ff0000,0x000000ff,0x00ffff00
# U,L,F,R,B,D palette indices. Cyclic slots agree with solver twists.
render_colors:
    .byte 0,3,2, 5,2,3, 5,1,2, 0,4,3, 5,3,4, 5,4,1, 0,1,4, 0,2,1
render_facelets:
    .byte 9,1,6,0
    .byte 13,1,3,0
    .byte 9,4,7,0
    .byte 13,4,0,0
    .byte 0,9,6,1
    .byte 4,9,7,2
    .byte 0,12,5,2
    .byte 4,12,2,1
    .byte 9,9,7,1
    .byte 13,9,0,2
    .byte 9,12,2,2
    .byte 13,12,1,1
    .byte 18,9,0,1
    .byte 22,9,3,2
    .byte 18,12,1,2
    .byte 22,12,4,1
    .byte 27,9,3,1
    .byte 31,9,6,2
    .byte 27,12,4,2
    .byte 31,12,5,1
    .byte 9,17,2,0
    .byte 13,17,1,0
    .byte 9,20,5,0
    .byte 13,20,4,0
render_sources:
    .byte 1, 4, 2, 0, 3, 5, 6
    .byte 4, 3, 2, 1, 0, 5, 6
    .byte 3, 0, 2, 4, 1, 5, 6
    .byte 0, 1, 2, 4, 5, 6, 3
    .byte 0, 1, 2, 5, 6, 3, 4
    .byte 0, 1, 2, 6, 3, 4, 5
    .byte 0, 2, 5, 3, 1, 4, 6
    .byte 0, 5, 4, 3, 2, 1, 6
    .byte 0, 4, 1, 3, 5, 2, 6
render_twists:
    .byte 1, 2, 0, 2, 1, 0, 0
    .byte 0, 0, 0, 0, 0, 0, 0
    .byte 1, 2, 0, 2, 1, 0, 0
    .byte 0, 0, 0, 1, 2, 1, 2
    .byte 0, 0, 0, 0, 0, 0, 0
    .byte 0, 0, 0, 1, 2, 1, 2
    .byte 0, 0, 0, 0, 0, 0, 0
    .byte 0, 0, 0, 0, 0, 0, 0
    .byte 0, 0, 0, 0, 0, 0, 0
    .bss
render_state:
    .zero 14
render_next:
    .zero 14
    .endif
    .section .note.GNU-stack,"",@progbits
